void main() {
  float age = 0.0;
  if (gl_FragCoord.x >= 0.0) age = unpack_age(texture2D(iChannel0, uv).rg);
  if (iTime < 0.1) age = hash(uv * 7.3) * lifespan(uv);
  else if (age >= lifespan(uv)) age = 0.0;
  else age += iTimeDelta / max(lifetime, 0.1);
  float hi = floor(age * 255.0);
  gl_FragColor = vec4(hi / 255.0, age * 255.0 - hi, 0.0, 1.0);
}

const float DSPAN = 0.0625;
const float JUMP = 0.03;

void main() {
  vec2 p1 = unpack_pos(texture2D(iChannel0, uv).rgb);
  vec2 d = p1 - unpack_pos(texture2D(iChannel1, uv).rgb);
  float age = unpack_age(texture2D(iChannel2, uv).rg);
  float span = lifespan(uv);
  float b = mix(dim, bright, hash(uv * 9.3))
          * smoothstep(0.0, 0.08, age) * smoothstep(span, span - 0.15, age)
          * smoothstep(-0.02, 0.1, depth(p1))
          * (1.0 - smoothstep(JUMP * 0.8, JUMP, length(d)));
  gl_FragColor = vec4(clamp(d / DSPAN + 0.5, 0.0, 1.0), b, 1.0);
}

void main() {
  vec2 o = 2.0 / iResolution.xy;
  float ink = 0.0;
  float halo = 0.0;
  if (gl_FragCoord.x >= 0.0) {
    ink = texture2D(iChannel0, uv).r;
    halo = texture2D(iChannel0, uv + vec2(o.x, 0.0)).r + texture2D(iChannel0, uv - vec2(o.x, 0.0)).r
         + texture2D(iChannel0, uv + vec2(0.0, o.y)).r + texture2D(iChannel0, uv - vec2(0.0, o.y)).r;
  }
  float px = 1.0 / iResolution.y;
  float y = uv.y - waterline(uv.x);
  vec3 col = mix(background, deep, clamp(y * 2.0, 0.0, 1.0));
  col += tail * glow * halo * 0.25;
  col = mix(col, tail, smoothstep(0.0, 0.45, ink));
  col = mix(col, head, smoothstep(0.5, 0.9, ink));
  float line = 1.0 - smoothstep(0.5 * px, 1.5 * px, abs(y));
  gl_FragColor = vec4(mix(col, surface, line * surface_glow), 1.0);
}
